package fetcher

import (
	"bytes"
	"crypto/x509"
	"encoding/pem"
	"errors"
	"strings"
	"testing"
	"time"
)

// Resolve checks metadata and key possession, not peer certificate validity.
// This unit test uses only generated bytes and temporary files, without TLS I/O.
func TestFileCredentialResolverSeparatesBindingAndCertificateExpiry(t *testing.T) {
	for _, scenario := range []string{"valid", "expired-metadata", "expired-certificate"} {
		t.Run(scenario, func(t *testing.T) {
			ca, _, issue := privateTLSClientFixtures(t)
			client, key := issue(3, func(v *x509.Certificate) {
				if scenario == "expired-certificate" {
					v.NotBefore, v.NotAfter = time.Now().Add(-2*time.Hour), time.Now().Add(-time.Hour)
				}
			})
			block, _ := pem.Decode(client)
			leaf, err := x509.ParseCertificate(block.Bytes)
			if err != nil {
				t.Fatal(err)
			}
			roots := x509.NewCertPool()
			if !roots.AppendCertsFromPEM(ca) {
				t.Fatal("fixture authority is unavailable")
			}
			_, verifyErr := leaf.Verify(x509.VerifyOptions{Roots: roots, CurrentTime: time.Now(), KeyUsages: []x509.ExtKeyUsage{x509.ExtKeyUsageClientAuth}})
			if scenario == "expired-certificate" {
				var invalid x509.CertificateInvalidError
				if !errors.As(verifyErr, &invalid) || invalid.Reason != x509.Expired {
					t.Fatal("expired specimen does not isolate certificate validity")
				}
			} else if verifyErr != nil {
				t.Fatal("valid specimen failed independent client certificate verification")
			}
			expiry := time.Now().Add(2 * time.Hour)
			if scenario == "expired-metadata" {
				expiry = time.Now().Add(-time.Hour)
			}
			directory := t.TempDir()
			origin := "https://catalog.example:443"
			metadata := stageMTLSCredentialFixture(t, directory, origin, "generation-one", expiry.UTC().Format(time.RFC3339Nano), client, key)
			publishCredentialMetadataFixture(t, directory, "partner", metadata)
			resolver, err := NewFileCredentialResolver(directory)
			if err != nil {
				t.Fatal(err)
			}
			resolved, err := resolver.Resolve(t.Context(), CredentialRequest{TenantID: routerTestTenant, Binding: "partner", Origin: origin})
			if scenario == "expired-metadata" {
				if err == nil || err.Error() != "credential binding has expired" || resolved.Revision != "" || len(resolved.Certificates) != 0 || len(resolved.Headers) != 0 {
					t.Fatalf("expired metadata returned usable credentials or the wrong error: %v", err)
				}
				if strings.Contains(err.Error(), directory) {
					t.Fatal("metadata refusal disclosed a credential path")
				}
				return
			}
			if err != nil || resolved.Revision != metadata.Revision || resolved.Origin != origin || len(resolved.Certificates) != 1 || len(resolved.Headers) != 0 || !bytes.Equal(resolved.Certificates[0].Certificate[0], leaf.Raw) {
				t.Fatalf("valid metadata and parseable key pair were not resolved intact: %v", err)
			}
		})
	}
}
